def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 9:
        return 'D'
    if n == 99:
        return 'D'

    my_defs = 0
    my_defs_with_next = 0
    opp_retaliations = 0
    opp_def_count = 0

    for i in range(n):
        my, opp = history[i]
        if my == 'D':
            my_defs += 1
            if i < n - 1:
                my_defs_with_next += 1
                if history[i+1][1] == 'D':
                    opp_retaliations += 1
        if opp == 'D':
            opp_def_count += 1

    if my_defs_with_next > 0:
        success_rate = (my_defs_with_next - opp_retaliations) / my_defs_with_next
    else:
        success_rate = 0.0

    target_rate = 0.3 * success_rate
    opp_def_rate = opp_def_count / n if n > 0 else 0.0

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if opp_def_rate > 0.7:
            return 'D'
        if n >= 2 and history[-2] == ('D', 'D'):
            return 'C'
        if opp_def_rate < 0.3 and n > 20 and rng.random() < 0.1:
            return 'C'
        return 'D'
    else:
        if my_defs < target_rate * n:
            if last_my == 'D':
                return 'C'
            return 'D'
        return 'C'
